CAT = "afspPractice"; SEG = "PRA"
# AFTR outline 3.4 to 3.7: preparer penalties (IRC 6694, 6695 with Rev. Proc. 2025-32 4.54 amounts for
# returns filed in 2027, 7216), due diligence (Form 8867, Treas. Reg. 1.6695-2), e-file rules (Pub. 1345),
# the Annual Filing Season Program (Rev. Proc. 2014-42, Pub. 5646) and Circular 230.
_a = max(1000, 1600 * 50 // 100); assert _a == 1000
_b = max(5000, 8000 * 75 // 100); assert _b == 6000
_sign = 20 * 65; assert _sign == 1300
_dd = 3 * 665; assert _dd == 1995

Q = [
("A preparer charged $1,600 for a return with an understatement from an unreasonable position. Under section 6694(a), the penalty is:",
 f"${_a:,}", ["$800", "$1,600", "$5,000"],
 "The section 6694(a) penalty is the greater of $1,000 or 50% of the income derived from the return. Half of $1,600 is $800, so $1,000 applies."),
("A preparer who willfully understated a client's tax earned an $8,000 fee for the return. Under section 6694(b), the penalty is:",
 f"${_b:,}", ["$5,000", "$4,000", "$8,000"],
 "For willful or reckless conduct the penalty is the greater of $5,000 or 75% of the income derived (IRC 6694(b)). 75% of $8,000 is $6,000."),
("A paid preparer fails to sign 20 returns filed in 2027. Under section 6695(b), the penalty is:",
 f"${_sign:,}", ["$13,300", "$650", "$33,000"],
 "For returns filed in 2027 the failure-to-sign penalty is $65 per return, up to $33,000 a year (Rev. Proc. 2025-32, section 4.54). 20 x $65 = $1,300."),
("For a return filed in 2027, a preparer who cashes a client's refund check faces a penalty of:",
 "$665 per check", ["$65 per check", "$665 per year", "$65 per return"],
 "Endorsing or negotiating a client's refund check brings a $665 penalty per check for 2027, with no yearly cap (Rev. Proc. 2025-32, section 4.54)."),
("Under section 7216, a preparer who knowingly discloses a client's return information without consent commits:",
 "A misdemeanor", ["A civil violation only", "A felony in all cases", "No offense if paid"],
 "IRC 7216 makes knowing or reckless unauthorized disclosure or use of return information a misdemeanor, punishable by a fine, up to a year in prison, or both. Section 6713 adds a civil penalty."),
("For a return claiming the earned income credit, the completed Form 8867 must be:",
 "Submitted with the return", ["Kept in the file only", "Given to the client only", "Mailed to the IRS each June"],
 "Completing Form 8867 and submitting it with the return is the first of the due diligence requirements; the preparer also computes the credit, meets the knowledge rule and keeps records (Treas. Reg. 1.6695-2)."),
("A preparer files a 2026 return claiming the earned income credit, the child tax credit and head of household status without meeting due diligence for any. The maximum penalty is:",
 f"${_dd:,}", ["$665", "$1,330", "$195"],
 "The section 6695(g) penalty for returns filed in 2027 is $665 per failure, and each of the three benefits is a separate failure: 3 x $665 = $1,995."),
("A 22-year-old client wants to claim two children aged 10 and 9 for the earned income credit. Under the knowledge requirement, the preparer must:",
 "Ask more questions and note the answers", ["Refuse to prepare the return", "Accept the claim as stated", "Call the IRS for approval"],
 "A preparer may not ignore information that seems incorrect, inconsistent or incomplete. Here the ages call for reasonable inquiries about the relationship, documented with the client's answers (Form 8867 instructions)."),
("A paid preparer must keep the records that support due diligence for each Form 8867 return for:",
 "3 years", ["2 years", "5 years", "7 years"],
 "Treas. Reg. 1.6695-2 requires keeping Form 8867, the worksheets and records of inquiries for 3 years from the latest of the due date, the filing date or other dates in the regulation."),
("Which is one of the four due diligence requirements for a Form 8867 return?",
 "Computing the credit correctly", ["Seeing the client's tax transcript", "Getting a notarized statement", "Visiting the client's home"],
 "The four requirements are completing and submitting Form 8867, computing the credits or using a computation worksheet, the knowledge requirement and keeping records (Form 8867 instructions)."),
("A client brings only her final pay stub and asks to e-file before her Form W-2 arrives. Under Pub. 1345, the preparer:",
 "May not e-file from a pay stub", ["May e-file with an estimate", "May e-file if the client signs", "May e-file after January 31"],
 "Authorized e-file providers may not use pay stubs or other earnings records in place of Forms W-2, W-2G or 1099-R to e-file an individual return (Pub. 1345)."),
("For a return using Form 8879, the taxpayer must sign and date the form:",
 "Before the return is sent", ["Within 30 days after filing", "After the IRS accepts it", "Only if a refund is due"],
 "The ERO may enter the PINs first, but the taxpayer must sign and date Form 8879 before the ERO originates the electronic submission (Pub. 1345)."),
("An ERO must keep signed Forms 8879 and 8878 for:",
 "3 years from the due date or receipt", ["1 year from acceptance", "5 years from signing", "Until the refund is paid"],
 "Pub. 1345 says Forms 8879 and 8878 are kept for three years from the return due date or the IRS received date, whichever is later."),
("After an e-filed return is accepted, the taxpayer can start checking its status in Where's My Refund within:",
 "24 hours of IRS receipt", ["Four weeks of IRS receipt", "72 hours of IRS receipt", "Ten days of IRS receipt"],
 "Pub. 1345 says taxpayers can check status 24 hours after the IRS receives an e-filed return, or four weeks after mailing a paper return."),
("A taxpayer authorizes an electronic withdrawal for a balance due on an e-filed Form 4868. The signature form used is:",
 "Form 8878", ["Form 8879", "Form 8453", "Form 8888"],
 "Form 8878, IRS e-file Signature Authorization for Form 4868 or Form 2350, is used when an extension is e-filed with an electronic funds withdrawal and a practitioner PIN (Pub. 1345)."),
("A specified tax return preparer files a client's return on paper at the client's request. The preparer attaches:",
 "Form 8948", ["Form 8508", "Form 8453", "Form 8879"],
 "Form 8948, Preparer Explanation for Not Filing Electronically, documents a paper filing by a preparer who must otherwise e-file. Form 8508 requests a waiver from filing information returns electronically."),
("Limited representation rights for an AFSP Record of Completion holder cover only returns that she:",
 "Prepared and signed", ["Reviewed for the client", "Filed in the last ten years", "Prepared under any PTIN"],
 "Rev. Proc. 2014-42 limits representation to examinations of returns or refund claims the preparer prepared and signed, or prepared if there is no signature space. It does not extend to appeals or collection."),
("A preparer prepared and signed a client's 2026 return. To represent the client in a 2027 audit of it, she needs a Record of Completion for:",
 "Both 2026 and 2027", ["2026 only", "2027 only", "Any year since 2016"],
 "Rev. Proc. 2014-42 requires a Record of Completion for the calendar year the return was prepared and signed and also for the year of the representation."),
("To receive an AFSP Record of Completion, a non-credentialed preparer must consent to the duties in Circular 230 subpart B and:",
 "Section 10.51", ["Section 10.6", "Section 10.3", "Section 10.8"],
 "The preparer must renew the PTIN and consent to the obligations in Subpart B and section 10.51 of Circular 230, which lists incompetence and disreputable conduct (AFSP FAQs)."),
("In advertising, an AFSP participant may not describe herself as:",
 "Certified by the IRS", ["Holding a Record of Completion", "An AFSP participant", "Compliant with AFSP rules"],
 "Rev. Proc. 2014-42 lets a participant say she holds a Record of Completion for the year, but she may not use the terms certified, enrolled or licensed or imply IRS endorsement."),
("A VITA quality reviewer with an active PTIN wants an AFSP Record of Completion. The continuing education she needs is:",
 "15 hours without the refresher", ["18 hours with the refresher", "6 hours of the refresher only", "24 hours of tax law"],
 "Pub. 5646 lists VITA quality reviewers and instructors among the groups exempt from the AFTR course; they need 15 hours: 3 of updates, 10 of federal tax law and 2 of ethics."),
("Under Circular 230 section 10.51, which act is disreputable conduct?",
 "Giving false information to the IRS", ["Charging a flat fee per return", "Declining a new client", "Advertising hourly rates"],
 "Section 10.51 lists knowingly giving false or misleading information to the IRS as disreputable conduct. AFSP participants consent to be bound by it."),
("A client in a fee dispute asks for his own records needed to file. Under Circular 230 section 10.28, the preparer must:",
 "Return them promptly", ["Hold them until paid", "Return them within 90 days", "Return copies only"],
 "Section 10.28 requires a practitioner to promptly return, on request, any client records necessary to comply with federal tax obligations, even during a fee dispute."),
("Under Circular 230 section 10.27, which fee arrangement for preparing an original return is prohibited?",
 "15% of the refund", ["A flat fee per form", "An hourly rate", "A fee set by complexity"],
 "A fee based on a percentage of the refund is a contingent fee, which section 10.27 bars for an original return. Fixed, hourly and complexity-based fees are allowed."),
]
